var n=`0143-ghapama`;var t=`world-0143`;var a=`AM`;var r=`western-asia`;var o=4;var s=127;var g={en:`Ghapama`,ua:`Гапама`};var d={en:`A classic dish from Armenia, featuring white rice, raisin, dried apricot, walnut. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: білий рис, родзинки, курага, волоський горіх. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`white-rice`,180,`g`],[`water`,450,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`raisin`,95,`g`],[`dried-apricot`,120,`g`],[`walnut`,100,`g`],[`honey`,95,`g`],[`ground-cinnamon`,4,`g`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:12,i:[[`pumpkin`,1400,`g`]]},{en:`Bake in a preheated 180°C oven for about 85 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 85 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:85,i:[[`unsalted-butter`,65,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,25,`g`]]}];var u={slug:n,id:t,country:`AM`,region:r,servings:4,minutes:127,title:g,text:d,steps:l};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,n as slug,l as steps,d as text,g as title};